import 'package:bloc/bloc.dart';import 'package:flutter/material.dart';import 'package:flutter_screenutil/flutter_screenutil.dart';class AnimatedCrossFadeCubit extends Cubit<CrossFadeStateModel> {  AnimatedCrossFadeCubit()      : super(CrossFadeStateModel(screenContainerHeight: 0.7.sh));  Future<void> tapChange() async {    final newMode = state.mode == CrossFadeState.showFirst        ? CrossFadeState.showSecond        : CrossFadeState.showFirst;    final newHeight = newMode == CrossFadeState.showFirst ? 0.7.sh : .8.sh;    emit(state.copyWith(screenContainerHeight: newHeight, mode: newMode));  }  void changeTypeUser() {    final bool type = state.carpenter ? false : true;    emit(state.copyWith(carpenter: type));  }  void viewForgetPasswordPage() {    final bool show = state.forgetPassword ? false : true;    emit(state.copyWith(forgetPassword: show));  }}class CrossFadeStateModel {  final CrossFadeState mode;  final double screenContainerHeight;  final bool carpenter;  final bool forgetPassword;  const CrossFadeStateModel({    this.carpenter = false,    this.mode = CrossFadeState.showFirst,    required this.screenContainerHeight,    this.forgetPassword = true,  });  CrossFadeStateModel copyWith({    CrossFadeState? mode,    bool? carpenter,    double? screenContainerHeight,    bool? forgetPassword,  }) {    return CrossFadeStateModel(      forgetPassword: forgetPassword ?? this.forgetPassword,      mode: mode ?? this.mode,      screenContainerHeight:          screenContainerHeight ?? this.screenContainerHeight,      carpenter: carpenter ?? this.carpenter,    );  }}